def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.

    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """

    stack = []
    tb = e.__traceback__
    while tb is not None:
        if len(stack) >= max_level:
            break
        frame = tb.tb_frame
        stack.append(frame)
        tb = tb.tb_next
    formatted_stack = []
    for frame in reversed(stack):
        formatted_stack.append(cls._format_frame(frame, max_path_level))
    formatted_exception = cls._format_exception(e, max_path_level)
    return '\n'.join(formatted_stack + [formatted_exception])

def _format_exception(self, e, max_path_level):
    exc_name = e.__class__.__name__
    exc_msg = str(e)
    if six.PY2:
        exc_msg = exc_msg.decode('utf-8')
    return '%s: %s' % (exc_name, exc_msg)

def _format_frame(self, frame, max_path_level):
    f_code = frame.f_code
    f_name = f_code.co_name
    f_filename = frame.f_code.co_filename
    f_lineno = frame.f_lineno
    f_path = f_filename.split('/')[-1]
    return '%s:%d (%s)' % (f_path, f_lineno, f_name)

