def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    bases = set(classes)
    for cls in classes:
        for base in cls.__bases__:
            bases.discard(base)
    return [cls for cls in classes if cls in bases]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        yield cls
        for base in cls.__bases__:
            yield from minimalBases([base])

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if len(classes) <= 1:
        return classes
    new_classes = []
    for cls in classes:
        add = True
        for check in classes:
            if cls != check and cls in check.__bases__:
                add = False
                break
        if add:
            new_classes.append(cls)
    return minimalBases(new_classes)

