def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if coord_name not in self.variables:
        raise ValueError(f"Coordinate '{coord_name}' does not exist in this dataset.")
    var = self.variables[coord_name]
    if var.ndim != 1:
        raise ValueError(f"Coordinate '{coord_name}' must be 1D, but found {var.ndim}D.")
    invalid_indices = np.where(var.values.isnull())[0]
    return invalid_indices

