    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if weight < 0:
        raise ValueError("fill weight must be non-negative")
    if not self.axes[0].contains(coord[0]) or not self.axes[1].contains(coord[1]):
        return
    i = self.axes[0].clip(coord[0])
    j = self.axes[1].clip(coord[1])
    self.nbins[i, j] += weight
    if self.ndim == 2:
        self.weights[i, j] += weight
    else:
        self.values[i, j, coord[2]] += weight

