def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        package_data = {}
        with zipfile.ZipFile(zip_path, 'r') as zipf:
            for zfile in zipf.infolist():
                if zfile.filename.startswith('./'):
                    continue
                file_name, file_ext = os.path.splitext(zfile.filename)
                if file_ext == '.xml':
                    try:
                        with zipf.open(zfile.filename, 'r') as zip_file:
                            xml_content = zip_file.read()
                        basename = os.path.basename(file_name)
                        if basename not in package_data:
                            package_data[basename] = []
                        package_data[basename].append(xml_content)
                    except:
                        print(f"Error reading {file_name}: {sys.exc_info()[0]}")
        return package_data
    except:
        print(f"Error reading {zip_path}: {sys.exc_info()[0]}")
        return {}

