    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_id, object_map in self._hierarchy.items():
        num_objects += 1
        if check_digests and object_map['digest'] != self._compute_digest(object_map['object']):
            if show_warnings:
                warnings.warn(f'Object {object_id} has an invalid digest.')
        elif validate_objects and not isinstance(object_map['object'], Object):
            if show_warnings:
                warnings.warn(f'Object {object_id} is not a valid Object.')
        else:
            good_objects += 1
    return num_objects, good_objects

