    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_id, object_map in self._object_maps.items():
        num_objects += 1
        if not object_map['object_deleted']:
            good_objects += 1
            if validate_objects:
                object_errors = self.validate_object(object_id, raise_exceptions=False, check_digests=check_digests, show_warnings=show_warnings)
                if object_errors:
                    print('Object errors:', object_errors)
                    good_objects -= 1
        if not object_map['alias_ids']:
            raise ValueError('Object has no alias_ids')
        if not object_map['mime_type']:
            raise ValueError('Object has no mime_type')
        for alias_id in object_map['alias_ids']:
            if not self._alias_ids.get(alias_id):
                raise ValueError('Alias ID does not exist')
        if object_map['mime_type'] not in self._mime_types:
            raise ValueError('MIME type is not supported')
    return num_objects, good_objects

