    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return 'File not found'

    if os.path.isdir(path):
        if len(os.listdir(path)) == 1:
            if os.path.isfile(os.path.join(path, 'inventory.json')):
                return 'inventory'
            elif os.path.isdir(os.path.join(path, '0=*')):
                return 'root'
            else:
                return 'other'
        elif len(os.listdir(path)) > 1:
            if os.path.isdir(os.path.join(path, '0=*')) and \
                    os.path.isfile(os.path.join(path, 'inventory.json')):
                return 'object'
            elif os.path.isdir(os.path.join(path, '0=*')):
                return 'root'
            elif os.path.isfile(os.path.join(path, 'inventory.json')):
                return 'inventory'
            else:
                return 'other'
        else:
            return 'other'
    else:
        return 'File not found'

