        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        for item in os.listdir(path):
            if item.startswith('0=') and item.endswith('.namaste'):
                namaste_file = path.join(item)
                with open(namaste_file, 'r') as f:
                    contents = f.read()
                    if contents.startswith('OCFL Specification'):
                        return 'root'
                    elif contents.startswith('OCFL Object'):
                        return 'object'
    except FileNotFoundError:
        return 'file'
    except OSError as e:
        return f'other: {e}'
    return 'other: unknown error'

