    """Amend the Bugzilla params"""
    for bug_id in bug_ids:
        result = self.request('bug/%s' % bug_id, 'GET')
        if 'error' in result:
            raise BugsyException(result['message'])
        bug = result['bugs'][0]
        for param in params:
            if param not in bug:
                raise BugsyException("Invalid parameter '%s' for updating bug" % param)
            bug[param] = params[param]
        result = self.request('bug/%s' % bug_id, 'PUT', json=bug)
        if 'error' in result:
            raise BugsyException(result['message'])
        return result

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not bug_ids:
        return params
    for bug_id in bug_ids:
        try:
            bug = self.get(bug_id)
        except BugsyException:
            continue
        for k, v in params.items():
            if k in bug.pvalues:
                bug.pvalues[k] = v
        bug.update()
    return params

