def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise ValueError("The number must be an integer.")
    if not isinstance(alphabet, list):
        raise ValueError("The alphabet must be a list.")
    if not all(isinstance(symbol, str) for symbol in alphabet):
        raise ValueError("The alphabet must contain only strings.")
    if not (padding is None or isinstance(padding, int)):
        raise ValueError("The padding must be an integer or None.")

    result = ""
    base = len(alphabet)
    if number == 0:
        return alphabet[0]
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding is not None:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)
    base = len(alphabet)
    if number == 0:
        return alphabet[0]
    if number < 0:
        is_negative = True
        number = -number
    else:
        is_negative = False
    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base
    if is_negative:
        digits.append('-')
    digits.reverse()
    return ''.join(digits).rjust(padding, alphabet[0])

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet)
    base = len(alphabet)
    result = ""
    while number > 0:
        number, remainder = divmod(number, base)
        result = alphabet[remainder] + result
    return result.zfill(padding)

