def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    subclasses = set()
    queue = [cls]
    while queue:
        parent = queue.pop(0)
        for child in parent.__subclasses__():
            if child not in subclasses:
                subclasses.add(child)
                queue.append(child)
    return subclasses

