def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.
    """
    precondition.AssertType(s, Text)
    precondition.AssertIn(platform, ["this", "1", "0"])

    if platform == "this":
        platform_id = "1" if PYTO_UNICODE_LITERALS_FLAG else "0"
    else:
        platform_id = platform

    if platform_id == "1":
        pattern = r"""'(?:'')*'|"(?:"")*"|()()"
    else:
        pattern = r'"(?:[^"]|"")*"|[^\s"]+'

    matches = list(re.finditer(pattern, s))

    if platform_id == "1":
        for match in matches:
            value = match.group(0)
            # remove quotation marks from quoted strings
            if value and value[0] in ['"', "'"]:
                value = value[1:-1]
            # replace quoted empty strings with an empty string
            value = value or ''
            yield value
    else:
        for match in matches:
            value = match.group(0)
            # remove quotation marks from quoted strings
            if value and value[0] == '"':
                value = value[1:-1]
            # replace quoted empty strings with an empty string
            value = value or ''
            yield value

def split(s: str, platform: str = 'this') -> List[str]:
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform

    if platform == 'win32':
        pattern = r'''(?:[^"']|"[^"]*"|'[^']*')+'''
    else:
        pattern = r'''(?:[^\s'"](?:(?:\\.|[^"'])*(?:"[^"]*"|\'[^'\']*\')?)*)'''

    return [chunk.strip() for chunk in re.findall(pattern, s)]

def split_multiplatform(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
