        raise ValueError("Invalid platform value")

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = '1' if sys.platform.startswith('posix') else '0'

    if platform == '1':
        rgx = re.compile(r'''(?:      # Group for either...
            "           # a quote
            (?:        # Group for either...
             [^"\\]    # any character that's not a quote or backslash
             |\\\\\\    # or any escaped character
             )*        # any number of times
           "          # a closing quote
            |         # or
            [^\s]+    # a sequence of non-whitespace characters
        )''', re.VERBOSE)

    elif platform == '0':
        rgx = re.compile(r'''(?:      # Group for either...
            "           # a quote
            (?:        # Group for either...
             [^"\\]    # any character that's not a quote or backslash
             |\\\\\\    # or any escaped character
             )*        # any number of times
           "          # a closing quote
            |         # or
            [^\s]+    # a sequence of non-whitespace characters
            (?:      # followed by either...
             \\\\?    # an escaped backslash
             |\\"     # or an escaped quote
            )*        # any number of times
        )''', re.VERBOSE)

    else:
        raise ValueError("invalid platform")

    return rgx.findall(s)

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("The archive_path does not exist.")

    archive_name = os.path.basename(archive_path)
    extract_path = os.path.join(tmp_path, archive_name)

    try:
        subprocess.check_call(["/bin/mkdir", "-p", extract_path])
    except subprocess.CalledProcessError as e:
        raise ValueError("Failed to create extract path.") from e

    try:
        subprocess.check_call(["/bin/tar", "-xf", archive_path, "-C", extract_path])
    except subprocess.CalledProcessError as e:
        raise ValueError("Failed to extract archive.") from e

    repo_url = os.path.join("file://", extract_path)
    return repo_url

def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    if not archive_path:
        raise ValueError("The argument 'archive_path' is required")
    if not tmp_path:
        raise ValueError("The argument 'tmp_path' is required")

    # Create a temporary directory to extract the archive
    with tempfile.TemporaryDirectory(dir=tmp_path) as tmp_dir:
        # Extract the archive
        archive_name = os.path.basename(archive_path)
        archive_ext = archive_name.split(".")[-1]
        if archive_ext in ("zip", "jar"):
            subprocess.run(["unzip", archive_path], cwd=tmp_dir, check=True)
        elif archive_ext == "tar":
            subprocess.run(["tar", "-xvf", archive_path], cwd=tmp_dir, check=True)
        else:
            raise ValueError("Unsupported archive format")

        # Get the extracted directory
        extracted_dir = os.path.join(tmp_dir, archive_name.split(".")[0])

        # Return the file url
        return "file://" + extracted_dir

