def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    frequency_regex = r"^(?P<value>\d+)\s+(?P<unit>\w+)$"
    match = re.match(frequency_regex, frequency)
    if match is None:
        raise ValueError("Invalid frequency: {}".format(frequency))

    value = int(match.group("value"))
    unit = match.group("unit").lower()
    if unit not in ["year", "month", "week", "day", "hour", "minute", "second"]:
        raise ValueError("Invalid frequency: {}".format(frequency))

    return datetime.timedelta(**{unit: value})

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    m = re.match(r"^(?P<num>\d+)\s*(?P<unit>\S+)$", frequency)
    if not m:
        raise ValueError("Failed to parse frequency string")

    num = int(m.group("num"))
    unit = m.group("unit")
    if unit.lower() in ["week", "weeks"]:
        return datetime.timedelta(weeks=num)
    elif unit.lower() in ["day", "days"]:
        return datetime.timedelta(days=num)
    elif unit.lower() in ["hour", "hours"]:
        return datetime.timedelta(hours=num)
    elif unit.lower() in ["minute", "minutes"]:
        return datetime.timedelta(minutes=num)
    elif unit.lower() in ["second", "seconds"]:
        return datetime.timedelta(seconds=num)
    else:
        raise ValueError("Unknown frequency unit '%s'" % unit)

