def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency == "always":
        return None

    match = re.match(r"^(\d+)\s*(day|week|month|year)s?$", frequency)
    if not match:
        raise ValueError("Invalid frequency: %s" % frequency)

    value, unit = match.groups()
    if unit == "day":
        return datetime.timedelta(days=int(value))
    elif unit == "week":
        return datetime.timedelta(weeks=int(value))
    elif unit == "month":
        return datetime.timedelta(days=int(value) * 30)
    elif unit == "year":
        return datetime.timedelta(days=int(value) * 365)

