            raise LenaValueError("Histogram with scale equal to zero can't be rescaled")
        self.histogram /= self._scale
        self._scale = other

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(candidate, iface):
        return False
    if tentative:
        for method_name in iface.__mro__:
            method = getattr(candidate, method_name, None)
            if method is None or not callable(method):
                return False
        return True
    else:
        for method_name in iface.__mro__:
            method = getattr(candidate, method_name, None)
            if method is None or not callable(method):
                return False
            if not getattr(method, "__coroutine_implementation__", None):
                return False
        return True

