def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not issubclass(candidate, iface):
        raise VerificationError("Class '%s' does not inherit from '%s'" % (candidate.__name__, iface.__name__))
    logger.debug("Verifying class '%s' against interface '%s'", candidate.__name__, iface.__name__)
    for attr in dir(iface):
        if attr.startswith('_') or attr in ['__class__', '__module__', '__metaclass__']:
            continue
        if not hasattr(candidate, attr):
            raise VerificationError("Class '%s' does not have the required attribute '%s'" % (candidate.__name__, attr))
        attr_candidate = getattr(candidate, attr)
        attr_interface = getattr(iface, attr)
        if isinstance(attr_interface, property):
            # check that property has corresponding getter and setter
            prop_candidate = property(attr_candidate.fget, attr_candidate.fset)
            prop_interface = property(attr_interface.fget, attr_interface.fset)
            if not prop_candidate.__eq__(prop_interface):
                raise VerificationError("Property '%s' in class '%s' does not match property in interface '%s'" % (attr, candidate.__name__, iface.__name__))
        elif not attr_candidate == attr_interface:
            raise VerificationError("Attribute '%s' in class '%s' does not match attribute in interface '%s'" % (attr, candidate.__name__, iface.__name__))
    logger.debug("Class '%s' verified successfully against interface '%s'", candidate.__name__, iface.__name__)

def verifyClass(iface, candidate, tentative=False):
        """
        Verify that the *candidate* might correctly provide *iface*.
        """
        if not isinstance(iface, Interface):
            raise TypeError("iface must be an instance of Interface")
        if not hasattr(candidate, "__bases__"):
            raise TypeError("candidate must be a class or a function")
        if not issubclass(candidate, iface):
            raise NotImplementedError("candidate does not implement iface")
        if tentative:
            if not is_tentative_source(candidate):
                raise TypeError("tentative requires a tentative source")
            if not is_tentative_target(iface):
                raise TypeError("tentative requires a tentative target")
            if not is_valid_tentative_type(candidate, iface):
                raise TypeError("tentative type is not valid")
        return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    bases = list(bases)
    metaclasses = set()
    while bases:
        base = bases.pop()
        if type(base) is not type:
            continue
        bases.extend(base.__bases__)
        metaclasses.add(base.__class__)
    metaclasses.discard(type)
    if len(metaclasses) == 0:
        return type
    elif len(metaclasses) == 1:
        return tuple(metaclasses)[0]
    else:
        return None

