    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set(mcls for b in bases if isinstance(b, type)
                      for mcls in (b.__class__,) + b.__class__.__bases__)
    metaclasses.discard(type)
    return metaclasses.pop() if len(metaclasses) == 1 else type

