    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    # Determine the metaclass by the most specific base class
    mcs = [base.__class__ for base in bases if hasattr(base, '__class__')]
    if not mcs:
        return type
    return mcs[-1]

