def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    _PROTOCOL_RE = re.compile(r'(https?:\/\/.*?)(?=\,|\s|$|[)])', re.I)
    _WIKI_RE = re.compile(r'\[\[([\w\s]+)\]\]', re.I)
    _URL_RE = re.compile(r'https?:\/\/[\w\/:%#\$&\?\(\)~\.=\+\-]+', re.I)

    def _add_link_attributes(m):
        url = m.group(0)
        if not _URL_RE.match(url):
            return url
        else:
            return '<a href="{}">{}</a>'.format(url, url)

    def _linkify_textual_links(m):
        text = m.group(0)
        url = None
        if text.startswith('http'):
            url = text
        elif text.startswith('www.'):
            url = 'http://{}'.format(text)
        else:
            url = _WIKI_RE.sub(r'https://en.wikipedia.org/wiki/\1', text)
        return '<a href="{}">{}</a>'.format(url, text)

    text = _PROTOCOL_RE.sub(_add_link_attributes, text)
    text = _URL_RE.sub(_linkify_textual_links, text)
    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    links = []
    for match in _RE_LINKS_MATCH.finditer(text):
        url = match.group(1)
        if match.group(2):
            text = match.group(2).strip()
        else:
            text = url
        link = '<a href="{}">{}</a>'.format(url, text)
        links.append(link)
    return ''.join(links)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Create a list of all link elements in the text
    links = []
    for match in _LINK_RE.finditer(text):
        link = match.group(1)
        if link not in links:
            links.append(link)

    # For each link, add the required attributes and linkify textual links
    for link in links:
        if link.startswith('http'):
            link = f'<a href="{link}" target="_blank" rel="noopener noreferrer">{link}</a>'
        elif link.startswith('/'):
            link = f'<a href="{link}" target="_blank">{link}</a>'
        else:
            link = f'<a href="/{link}">{link}</a>'
        text = text.replace(f'[{link}]({link})', link)

    return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        req = requests.head(url, headers={'User-Agent': 'Content-Type Definer'})
        return req.headers.get('Content-Type', '').lower()
    except requests.RequestException:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
        if not scheme in ('http', 'https', 'ftp', 'ftps'):
            return None
        req = Urllib2HeadRequest(url, headers={'Host': netloc})
        resp = urlopen(req)
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('Content-Type')
    finally:
        resp.close()
    return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        req = urllib.request.Request(url, method="HEAD")
        resp = urllib.request.urlopen(req)
        content_type = resp.info().get("Content-Type")
        return content_type
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return None
        raise e
    except urllib.error.URLError as e:
        raise e

