def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not doc.has_element(signature):
        raise ValueError("Signature element is missing.")

    signer = Signer(public_key)
    try:
        signer.verify(signature, doc)
        return True
    except (InvalidSignatureError, UnknownCertificateError):
        return False

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not isinstance(public_key, RSA.RsaKey):
        raise ValueError("public_key must be an RSA key")
    if not isinstance(doc, etree._Element):
        raise ValueError("doc must be an XML element")
    if not isinstance(signature, etree._Element):
        raise ValueError("signature must be an XML element")

    signature_alg = signature.get("Algorithm")
    if signature_alg != "http://www.w3.org/2000/09/xmldsig#rsa-sha1":
        raise ValueError("Unknown signature algorithm: %s" % signature_alg)

    signature_value = base64.b64decode(signature.text)
    digest_alg = signature.get("DigestAlgorithm")
    if digest_alg != "http://www.w3.org/2001/04/xmlenc#sha256":
        raise ValueError("Unknown digest algorithm: %s" % digest_alg)

    digest_value = base64.b64decode(signature.get("DigestValue"))
    sig_hash = hashlib.sha256(digest_value)

    return public_key.verify(sig_hash, signature_value)

